import{_ as t,o as a,c as o,ah as n}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Candidature and admission","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/apprenant/candidature.md","filePath":"src/en/guide/apprenant/candidature.md"}'),r={name:"en/guide/apprenant/candidature.md"};function i(s,e,d,h,u,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="candidature-and-admission" tabindex="-1">Candidature and admission <a class="header-anchor" href="#candidature-and-admission" aria-label="Permalink to &quot;Candidature and admission&quot;">​</a></h1><p>Before being a learner, you are a candidate. Admission takes four steps, always in this order: <strong>application</strong>, <strong>interview</strong>, <strong>test</strong>, <strong>decision</strong>.</p><h2 id="_1-submit-your-candidature" tabindex="-1">1. Submit your candidature <a class="header-anchor" href="#_1-submit-your-candidature" aria-label="Permalink to &quot;1. Submit your candidature&quot;">​</a></h2><p>You apply on the NextBoxx website: you choose a published program (the training), the <strong>format</strong> that suits you (online, hybrid or in person), and you attach your file. The website passes your candidature on to Kura.</p><ul><li>Your NextBoxx account is created if it does not exist, or reused if it already exists for your e-mail address.</li><li>You receive an acknowledgement. For a new account, it contains the link to <a href="./../premiers-pas.html#create-your-account">choose your password</a>, valid for 7 days.</li><li>You can have <strong>only one candidature in progress at a time</strong>, whatever the training.</li></ul><p>You then follow your file in Kura, in <strong>Journeys → My candidature</strong>: the current step, the dates, your test score and the decision. The team&#39;s internal reports do not appear there.</p><div class="tip custom-block"><p class="custom-block-title">Minor candidate</p><p>If you are a minor, your file is flagged from the moment you apply. Your enrolment can only succeed with the consent and signature of a legal guardian (see <a href="./inscription.html#if-you-are-a-minor">Enrolment and agreement</a>).</p></div><h2 id="_2-the-interview" tabindex="-1">2. The interview <a class="header-anchor" href="#_2-the-interview" aria-label="Permalink to &quot;2. The interview&quot;">​</a></h2><p>An admissions advisor takes your file in charge and becomes your contact. They hold an interview with you, in principle <strong>within 5 working days</strong> of the application (Monday to Friday, excluding public holidays).</p><p>When the interview is closed, you receive the test link by e-mail.</p><h2 id="_3-the-admission-test" tabindex="-1">3. The admission test <a class="header-anchor" href="#_3-the-admission-test" aria-label="Permalink to &quot;3. The admission test&quot;">​</a></h2><p>The test is a multiple-choice quiz, available through the link you received, <strong>without signing in</strong>. A few rules to know before starting:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Link</td><td>Single use, valid <strong>48 hours</strong> to start</td></tr><tr><td>Attempts</td><td><strong>2</strong> at most</td></tr><tr><td>Time</td><td><strong>45 minutes</strong> per attempt, from the moment the quiz opens</td></tr><tr><td>Questions</td><td>10, drawn from a bank of 20 validated questions. The 2nd attempt offers different questions from the 1st</td></tr></tbody></table><p>At 45 minutes, the answers already given are sent as they are; the attempt counts as used. Your <strong>score is shown as soon as you submit</strong>.</p><p>The pass mark is <strong>6 correct answers out of 10</strong>. A passed attempt closes the test; otherwise it closes after the 2nd attempt. The score is <strong>indicative</strong>: your file goes to decision whatever the result, and the advisor decides.</p><p>If the link has expired, or if your attempts are used up for lack of time, the team is reminded. The advisor can send you a new link (your attempts are then reset) or close the test.</p><h2 id="_4-the-decision" tabindex="-1">4. The decision <a class="header-anchor" href="#_4-the-decision" aria-label="Permalink to &quot;4. The decision&quot;">​</a></h2><p>The advisor gives their <strong>reasoned</strong> decision within 3 working days of the test. You receive it by e-mail, with a <strong>decision letter</strong> as a PDF. You also find it in <strong>My candidature</strong> and in <strong>My documents</strong>. The advisor&#39;s reason stays internal.</p><ul><li><strong>Admitted.</strong> Your account becomes a <strong>Learner</strong> account and your enrolment is created. The advisor may have placed you in a cohort; otherwise, the Pedagogical Coordinator assigns you later and tells you by e-mail. What follows is in <a href="./inscription.html">Enrolment and agreement</a>.</li><li><strong>Refused.</strong> The file is closed. No payment is due and no access to Sève is opened.</li></ul><h3 id="applying-again-after-a-refusal" tabindex="-1">Applying again after a refusal <a class="header-anchor" href="#applying-again-after-a-refusal" aria-label="Permalink to &quot;Applying again after a refusal&quot;">​</a></h3><p>You can submit a new file <strong>7 days</strong> after a refusal. It is attached to your account and linked to the previous one, which stays visible in the history. For the new test, the questions from the first attempt of your previous test are left out of the draw as far as the bank allows.</p><p>A refused file is kept for 12 months, then <strong>anonymized</strong>: only the program, format, dates, scores and decision remain, for statistics. The motivation, attachments, reports, test answers and reason are deleted, and the file is detached from your account.</p>',22)])])}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
